import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.BrO6lPIi.js";const _=JSON.parse('{"title":"模型与依赖管理","description":"语音输入的可用性由两件**独立可安装**的东西决定：运行时依赖（`sherpa-onnx-node`，约 300MB+）与识别模型包（每个几百 MB）。","frontmatter":{"title":"模型与依赖管理","description":"语音输入的可用性由两件**独立可安装**的东西决定：运行时依赖（`sherpa-onnx-node`，约 300MB+）与识别模型包（每个几百 MB）。"},"headers":[],"relativePath":"语音输入/模型与依赖管理/index.md","filePath":"语音输入/模型与依赖管理/index.md","lastUpdated":null}'),r={name:"语音输入/模型与依赖管理/index.md"};function c(s,e,n,i,l,h){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="模型与依赖管理" tabindex="-1">模型与依赖管理 <a class="header-anchor" href="#模型与依赖管理" aria-label="Permalink to &quot;模型与依赖管理&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/model-pack.js" target="_blank" rel="noreferrer">agent/src/asr/model-pack.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/model-catalog.js" target="_blank" rel="noreferrer">agent/src/asr/model-catalog.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/model-download.js" target="_blank" rel="noreferrer">agent/src/asr/model-download.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/detect.js" target="_blank" rel="noreferrer">agent/src/asr/detect.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/install.js" target="_blank" rel="noreferrer">agent/src/asr/install.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/config.js" target="_blank" rel="noreferrer">agent/src/asr/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/routes.js" target="_blank" rel="noreferrer">agent/src/asr/routes.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json" target="_blank" rel="noreferrer">agent/package.json</a></li></ul></details><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>语音输入的可用性由两件<strong>独立可安装</strong>的东西决定：运行时依赖（<code>sherpa-onnx-node</code>，约 300MB+）与识别模型包（每个几百 MB）。两者都刻意做成「按需下载、失败可降级、卸载不影响主链路」。</p><p>本文说明落盘布局、模型包的校验契约、下载与续传策略，以及依赖检测如何在「不想为未安装用户白付一次 ONNX 加载」这个前提下保持准确。</p><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#落盘布局">落盘布局</a></li><li><a href="#模型包契约">模型包契约</a></li><li><a href="#内置推荐目录">内置推荐目录</a></li><li><a href="#下载与续传">下载与续传</a></li><li><a href="#哈希缓存">哈希缓存</a></li><li><a href="#依赖检测">依赖检测</a></li><li><a href="#依赖一键安装">依赖一键安装</a></li><li><a href="#环境变量">环境变量</a></li><li><a href="#结论">结论</a></li></ol><h2 id="落盘布局" tabindex="-1">落盘布局 <a class="header-anchor" href="#落盘布局" aria-label="Permalink to &quot;落盘布局&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.ai-helper-agent/</span></span>
<span class="line"><span>├── asr/</span></span>
<span class="line"><span>│   ├── asr-config.json          # 用户配置（开关 / 语言 / 模型 id / 空闲卸载）</span></span>
<span class="line"><span>│   ├── hash-cache.json          # 模型文件 sha256 缓存</span></span>
<span class="line"><span>│   └── models/&lt;id&gt;/             # 模型包：manifest.json + ONNX + tokens 等</span></span>
<span class="line"><span>│       └── manifest.json</span></span>
<span class="line"><span>├── asr-install-state.json       # 依赖安装任务状态</span></span>
<span class="line"><span>└── asr-model-download-state.json# 模型下载任务状态</span></span></code></pre></div><p>模型目录<strong>固定不开放配置</strong>：用户需要的是「模型放哪」的可读提示，不是可选项。展示时把 home 前缀折叠为 <code>~</code>，避免配置页出现含用户名的长绝对路径。</p><h2 id="模型包契约" tabindex="-1">模型包契约 <a class="header-anchor" href="#模型包契约" aria-label="Permalink to &quot;模型包契约&quot;">​</a></h2><p><code>scanModels</code> 只认 <code>&lt;models&gt;/&lt;id&gt;/manifest.json</code>。校验按顺序短路，第一个失败即返回原因：</p><table tabindex="0"><thead><tr><th>顺序</th><th>检查</th><th>失败原因码</th></tr></thead><tbody><tr><td>1</td><td><code>manifest.json</code> 存在</td><td><code>manifest_missing</code></td></tr><tr><td>2</td><td>是合法 JSON 且为对象</td><td><code>manifest_invalid_json</code> / <code>manifest_not_object</code></td></tr><tr><td>3</td><td><code>schema === 1</code></td><td><code>manifest_schema_unsupported</code></td></tr><tr><td>4</td><td><code>engine === &#39;sherpa-onnx&#39;</code></td><td><code>engine_unsupported</code></td></tr><tr><td>5</td><td><code>id</code> 非空</td><td><code>manifest_invalid_id</code></td></tr><tr><td>6</td><td><code>kind ∈ {online, offline, vad}</code></td><td><code>manifest_invalid_kind</code></td></tr><tr><td>7</td><td><code>files</code> 非空，且每项都在包目录内、存在、非空</td><td><code>manifest_no_files</code> / <code>file_outside_pack</code> / <code>file_missing</code> / <code>file_empty</code></td></tr><tr><td>8</td><td><code>sha256</code>（可选）与文件实际摘要一致</td><td><code>file_unreadable</code> / <code>sha256_mismatch</code></td></tr><tr><td>9</td><td>按 <code>kind</code> 必需的文件定位键齐全</td><td><code>manifest_missing_model_or_tokens</code> 等</td></tr></tbody></table><p><code>file_outside_pack</code> 这一条是安全边界：<code>files</code> 里写 <code>../../etc/passwd</code> 会被拒绝，包只能引用自身目录内的文件。</p><p><code>sha256</code> 字段是可选的——本地自建模型包往往没有现成摘要，此时跳过哈希校验但仍要求文件存在。<code>manifest.schema</code> 与 <code>model-pack.js</code> 的 <code>MANIFEST_SCHEMA</code> 必须一致，升级格式即等于拒绝旧包。</p><h2 id="内置推荐目录" tabindex="-1">内置推荐目录 <a class="header-anchor" href="#内置推荐目录" aria-label="Permalink to &quot;内置推荐目录&quot;">​</a></h2><p>内置清单是<strong>自动下载的唯一事实来源</strong>，调用方不能传任意 id，因此不存在拼路径穿越的入口：</p><table tabindex="0"><thead><tr><th>id</th><th>kind</th><th>用途</th></tr></thead><tbody><tr><td><code>sense-voice-zh-en-ja-ko-yue</code></td><td><code>offline</code></td><td>松手后整段高精度转写，自动带标点、数字规整</td></tr><tr><td><code>streaming-zipformer-bilingual-zh-en</code></td><td><code>online</code></td><td>边说边出的低延迟草稿</td></tr></tbody></table><p>下载端点默认 <code>https://hf-mirror.com</code>（官方站点在部分网络下直连不可达），可用 <code>AI_HELPER_ASR_HF_ENDPOINT</code> 指向官方站点或自建代理。每个文件的 <code>size</code> 与 <code>sha256</code> 都以本地实测跑通的包为准，不按上游目录动态推导——上游新增文件不应该改变加载参数。</p><p>清单之外还有一条完全离线的分发路径：在能上网的机器上备好同构目录，用「从文件夹导入」或直接拷进 <code>models/</code>。</p><h2 id="下载与续传" tabindex="-1">下载与续传 <a class="header-anchor" href="#下载与续传" aria-label="Permalink to &quot;下载与续传&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>说明</th></tr></thead><tbody><tr><td>逐文件下载</td><td>不走 <code>.tar.bz2</code>（Node 无内置 bzip2），HF 支持单文件 HTTP 取</td></tr><tr><td>临时目录</td><td>落 <code>models/.&lt;id&gt;.part/</code>；点开头的目录被扫描跳过，半成品对外不可见</td></tr><tr><td>原子发布</td><td>全部文件就绪后写 <code>manifest.json</code>，再 rename 成 <code>models/&lt;id&gt;/</code></td></tr><tr><td>秒级续传</td><td>已存在且字节数与哈希都匹配的文件直接跳过，中断重试不从零开始</td></tr><tr><td>边写边哈希</td><td>逐块算 sha256 与写入同步，不额外读一遍盘；不匹配即删该文件</td></tr><tr><td>无数据超时</td><td>60 秒收不到数据即失败，不让用户干等</td></tr><tr><td>状态持久化</td><td>代理重启后把「运行中」收敛为「已中止」，不出现假进度</td></tr></tbody></table><h2 id="哈希缓存" tabindex="-1">哈希缓存 <a class="header-anchor" href="#哈希缓存" aria-label="Permalink to &quot;哈希缓存&quot;">​</a></h2><p>单个模型包可达数百 MB，每次扫描全量重算不可接受。<code>sha256OfFile</code> 用 <code>(path, size, mtime)</code> 作缓存键，文件一变即失效，结果落 <code>hash-cache.json</code>。</p><p>计算本身是<strong>分块读</strong>：<code>openSync</code> + 4MB <code>readSync</code> 循环，内存峰值固定 4MB。整包 <code>readFileSync</code> 在 <code>MAX_MODEL_FILE_BYTES</code>（8GB）这种上限下会先撞上 Node 的 Buffer 上限（约 2GB）并抛 <code>ERR_FS_FILE_TOO_LARGE</code>，而这里只需要顺序过一遍算摘要。</p><h2 id="依赖检测" tabindex="-1">依赖检测 <a class="header-anchor" href="#依赖检测" aria-label="Permalink to &quot;依赖检测&quot;">​</a></h2><p><code>detect.js</code> 与 RAG 的检测刻意不同，原因是 ASR 依赖的 ONNX 运行时加载即常驻数百 MB：</p><ol><li><strong>零成本磁盘判定</strong>：<code>asr-config.json</code> 或 <code>node_modules/sherpa-onnx-node/package.json</code> 任一缺失 → 直接判不可用，不起子进程。</li><li><strong>子进程确认</strong>：只有「看起来装过」才 <code>spawn</code> 探测脚本 <code>require</code> 一次，超时 <strong>3 秒</strong>（RAG 是 60 秒，但这里只 <code>require</code> 一个包）。</li><li><strong>不自动重装</strong>：只记录 <code>everSucceeded</code>，状态里提示「依赖已被清理，请点击重新安装」。</li></ol><p><code>AI_HELPER_ASR_DEPS=0</code> 会强制判为不可用，且磁盘判定也同步返回 <code>false</code>，避免状态里出现「<code>ready=false</code> 但 <code>packageOnDisk=true</code>」的矛盾组合。</p><h2 id="依赖一键安装" tabindex="-1">依赖一键安装 <a class="header-anchor" href="#依赖一键安装" aria-label="Permalink to &quot;依赖一键安装&quot;">​</a></h2><p>安装清单来自 agent 包自身 <code>package.json</code> 的 <code>asrDependencies</code>（当前为 <code>sherpa-onnx-node: ^2.0.0</code>），不接受调用方传入包名：</p><table tabindex="0"><thead><tr><th>设计点</th><th>说明</th></tr></thead><tbody><tr><td>显式 spec</td><td>命令携带由清单构建的 <code>pkg@spec</code>，不接受外部输入，无注入面</td></tr><tr><td>无 shell</td><td>非 Windows 严格 <code>shell: false</code>；Windows 优先用当前 Node 直执行 <code>npm-cli.js</code>，探测不到才降级并加引号</td></tr><tr><td>单任务 + 安装锁</td><td>同一时刻仅一个安装任务，超时上限 10 分钟</td></tr><tr><td>进程组杀</td><td>POSIX 以 <code>detached: true</code> 启动，终止走进程树组杀</td></tr><tr><td>状态持久化</td><td><code>asr-install-state.json</code>，重启后「运行中」收敛为「已中止」</td></tr><tr><td>完成后复检</td><td>在子进程重新探测，防「装上但加载失败」的假成功</td></tr></tbody></table><p><code>--with-asr</code> 安装参数（<code>install.sh</code>）走的是同一条清单，区别只是发生在 Agent 首次安装期间。</p><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>作用</th></tr></thead><tbody><tr><td><code>AI_HELPER_ASR_ROOT</code></td><td>覆盖 ASR 数据根目录（测试隔离 / 自定义位置）</td></tr><tr><td><code>AI_HELPER_ASR_DEPS</code></td><td>置 <code>0</code> 强制判依赖不可用</td></tr><tr><td><code>AI_HELPER_ASR_HF_ENDPOINT</code></td><td>覆盖模型下载端点</td></tr><tr><td><code>AI_HELPER_ASR_MAX_RECORDING_MS</code></td><td>单次录音上限，默认 300000</td></tr><tr><td><code>AI_HELPER_ASR_SESSION_IDLE_MS</code></td><td>会话空闲回收，默认 30000</td></tr><tr><td><code>AI_HELPER_ASR_MAX_SESSIONS</code></td><td>并发会话上限，默认 1</td></tr><tr><td><code>AI_HELPER_ASR_RSS_LIMIT</code></td><td>RSS 保护阈值，默认 3.5GB</td></tr><tr><td><code>AI_HELPER_ASR_OFFLINE_TIMEOUT_MS</code></td><td>单次定稿推理超时，默认 180000</td></tr></tbody></table><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>模型与依赖管理遵守一条共同原则：<strong>失败要可解释、可重试、且不污染主链路</strong>。所以每个校验失败都有明确原因码、下载中断可以续传、安装失败不会留下半成品目录、依赖缺失时按钮直接隐藏而不是点了报错。新增模型来源时，应复用这套契约而不是另开一条路径。</p>`,37)])])}const g=t(r,[["render",c]]);export{_ as __pageData,g as default};
